-- -----------------------------------------------------------------------------------------------------
-- 材料定义表建表初始化

CREATE TABLE IF NOT EXISTS material_def (
    ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    `name` VARCHAR(20) NOT NULL COMMENT '材料名称',
    `form` VARCHAR(20) NOT NULL COMMENT '材料形态',
    `identifier` VARCHAR(50) NOT NULL UNIQUE COMMENT '材料标识',
    `comment` VARCHAR(100) NULL COMMENT '材料描述'
) COMMENT '材料定义表';

INSERT IGNORE INTO material_def (`id`, `name`, `form`, `identifier`, `comment`) VALUES
    (1, 'Silicon', 'Crystal', 'Si_crystal', 'Si晶体硅, [Si_crystal]_freq-r-i_0.0310-310um_ByFranta-300K_2017'),
    (2, 'Germanium', 'pending', 'pending','Ge 锗, pending'),
    (3, 'Titanium dioxide', 'ThinFilm', 'TiO2_ThinFilm', 'TiO2薄膜, [TiO2_ThinFilm]_freq-r-i_0.211-1.69um_ByZhukovsky_2015'),
    (4, 'Silicon dioxide', 'ThinFilm', 'SiO2_ThinFilm', 'SiO2薄膜, [SiO2_ThinFilm]_freq-r-i_0.0275-125um_ByFranta-25C_2016');


-- -----------------------------------------------------------------------------------------------------
-- 定义形状信息

CREATE TABLE IF NOT EXISTS shape_def (
    ID INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT '主键',
    `name` VARCHAR(40) NOT NULL COMMENT '形状名称',
    `zn` VARCHAR(80) NOT NULL COMMENT '中文名',
    `parameters_num` TINYINT UNSIGNED NOT NULL COMMENT '参数个数',
    `col_names` VARCHAR(300) NOT NULL COMMENT '参数名称(列名)',
    `tables` VARCHAR(100) NOT NULL COMMENT '表名'
);

INSERT IGNORE INTO shape_def (`ID`, `name`, `zn`, `parameters_num`, `col_names`, `tables`) VALUES
    (1, 'generic_parameters', '通用参数', 8, '["height","period","thickness","e_theta","e_phi"]', '["generic_parameters"]'),
    (2, 'CuboidPillar', '矩形截面柱体', 7, '["length","width"]', '["CuboidPillar_parameters","CuboidPillar_freq_resp"]'),
    (3, 'SquarePillar', '正方截面柱体', 6, '["side_length"]', '["SquarePillar_parameters","SquarePillar_freq_resp"]'),
    (4, 'Cylinder', '圆柱体', 6, '["radius"]', '["Cylinder_parameters","Cylinder_freq_resp"]'),
    (5, 'Cross', '一般十字截面柱体', 9, '["long_length","long_width","short_length","short_width"]', '["Cross_parameters","Cross_freq_resp"]'),
    (6, 'SquareHole', '方形孔洞', 6, '["side_length"]', '["SquareHole_parameters","SquareHole_freq_resp"]'),
    (7, 'SymmetricCross', '对称十字型', 7, '["width","length"]', '["SymmetricCross_parameters","SymmetricCross_freq_resp"]'),
    (8, 'SquareRing', '方形环', 7, '["inner_length","outer_length"]', '["SquareRing_parameters","SquareRing_freq_resp"]');


