-- -----------------------------------------------------------------------------------------------------
-- 所有形状单元结构基本参数（一级）表建表

CREATE TABLE IF NOT EXISTS generic_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `substrate_material_id` INT UNSIGNED NOT NULL COMMENT '基底材料ID',
    `pillar_material_id` INT UNSIGNED NOT NULL COMMENT '单元材料ID',
    `S_Param_id` INT UNSIGNED NOT NULL COMMENT 'S参数ID',
    `height` DECIMAL(12,6) NOT NULL COMMENT '单元结构高度',
    `period` DECIMAL(12,6) NOT NULL COMMENT '单元结构排布周期',
    `thickness` DECIMAL(12,6) NOT NULL COMMENT '单元结构基底厚度',
    `E_theta` DOUBLE NOT NULL COMMENT '入射角 theta',
    `E_phi` DOUBLE NOT NULL COMMENT '入射角 phi',
    `hash` CHAR(32) NULL COMMENT '基本参数哈希值',
    FOREIGN KEY (`substrate_material_id`) REFERENCES material_def(ID),
    FOREIGN KEY (`pillar_material_id`) REFERENCES material_def(ID),
    FOREIGN KEY (`S_Param_id`) REFERENCES s_parameter(ID)
) COMMENT '单元结构基本参数表';


-- -----------------------------------------------------------------------------------------------------
-- 各形状特殊（二级）单元结构参数表建表

CREATE TABLE IF NOT EXISTS CuboidPillar_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '长',
    `width` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '宽'
) COMMENT '矩形截面方体单元结构特征参数表';

CREATE TABLE IF NOT EXISTS SquarePillar_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `side_length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '边长'
) COMMENT '正方形截面方体单元结构特征参数表';

CREATE TABLE IF NOT EXISTS Cylinder_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `radius` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '半径'
) COMMENT '圆柱体单元结构特征参数表';

CREATE TABLE IF NOT EXISTS Cross_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `long_length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '长边，长',
    `long_width` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '长边，短',
    `short_length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '宽边，长',
    `short_width` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '宽边，短'
) COMMENT '十字形单元结构特征参数表';

CREATE TABLE IF NOT EXISTS SquareHole_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `side_length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '边长'
) COMMENT '方形孔洞单元结构特征参数表';

CREATE TABLE IF NOT EXISTS SymmetricCross_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `width` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '宽度',
    `length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '长度'
) COMMENT '对称十字形单元结构特征参数表';

CREATE TABLE IF NOT EXISTS SquareRing_parameters (
    ID BINARY(16) NOT NULL PRIMARY KEY,
    `inner_length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '内径边长',
    `outer_length` DECIMAL(12,6) UNSIGNED NOT NULL COMMENT '外径边长'
) COMMENT '方形环单元结构特征参数表';


